import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.1
.target sm_89
.address_size 64

// Matrix-vector multiplication: C[M,1] = A[M,K] * B[K,1]
// Launch configuration: grid.x = M, block.x = 256
.visible .entry matvec_kernel(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 K
)
{
    .reg .pred  %p<7>;
    .reg .b32   %r<20>;
    .reg .b64   %rd<30>;
    .reg .f32   %f<8>;

    .shared .align 4 .b8 sdata[1024]; // 256 threads * 4 bytes

    // Load parameters
    ld.param.u64 %rd1, [A_ptr];
    ld.param.u64 %rd2, [B_ptr];
    ld.param.u64 %rd3, [C_ptr];
    ld.param.u32 %r10, [M];
    ld.param.u32 %r11, [K];

    // Thread/block indices
    mov.u32 %r0, %ctaid.x;   // row index
    mov.u32 %r1, %tid.x;     // thread id
    mov.u32 %r2, %ntid.x;    // blockDim.x

    // Guard: if row >= M, exit
    setp.ge.u32 %p0, %r0, %r10;
    @%p0 bra DONE;

    // Initialize sum accumulator
    mov.f32 %f0, 0f00000000;

    // Compute base element index for row: base = row * K (64-bit)
    cvt.u64.u32 %rd10, %r0;     // row -> u64
    cvt.u64.u32 %rd11, %r11;    // K -> u64
    mul.lo.u64 %rd12, %rd10, %rd11; // base element index

    // Loop over K with stride blockDim.x
    mov.u32 %r3, %r1; // i = tid.x
LOOP_START:
    setp.ge.u32 %p1, %r3, %r11;
    @%p1 bra LOOP_END;

    // idx = base + i (64-bit), compute byte offsets
    cvt.u64.u32 %rd13, %r3;
    add.u64 %rd14, %rd12, %rd13;     // element index for A[row, i]
    shl.b64 %rd15, %rd14, 2;         // *4 bytes
    shl.b64 %rd16, %rd13, 2;         // B[i] offset

    add.u64 %rd17, %rd1, %rd15;      // &A[row, i]
    add.u64 %rd18, %rd2, %rd16;      // &B[i]

    ld.global.f32 %f1, [%rd17];
    ld.global.f32 %f2, [%rd18];
    fma.rn.f32 %f0, %f1, %f2, %f0;

    add.u32 %r3, %r3, %r2; // i += blockDim.x
    bra LOOP_START;

LOOP_END:
    // Write partial sum to shared memory: sdata[tid] = sum
     mov.u64 %rd20, sdata;
    cvt.u64.u32 %rd21, %r1;
    shl.b64 %rd22, %rd21, 2;
    add.u64 %rd23, %rd20, %rd22;
    st.shared.f32 [%rd23], %f0;

    // Synchronize before reduction
    bar.sync 0;

    // Parallel reduction in shared memory
    // stride = blockDim.x / 2
    mov.u32 %r4, %r2;
    shr.u32 %r4, %r4, 1;

REDUCTION_LOOP:
    setp.eq.u32 %p2, %r4, 0;
    @%p2 bra REDUCTION_END;

    setp.lt.u32 %p3, %r1, %r4;
    @!%p3 bra SKIP_ADD;

    // neighbor index = tid + stride
    add.u32 %r5, %r1, %r4;
    cvt.u64.u32 %rd24, %r5;
    shl.b64 %rd25, %rd24, 2;
    add.u64 %rd26, %rd20, %rd25;

    // Load self and neighbor, add, store back
    ld.shared.f32 %f3, [%rd26];
    ld.shared.f32 %f4, [%rd23];
    add.f32 %f5, %f4, %f3;
    st.shared.f32 [%rd23], %f5;

SKIP_ADD:
    bar.sync 0;
    shr.u32 %r4, %r4, 1;
    bra REDUCTION_LOOP;

REDUCTION_END:
    // Thread 0 writes the result to C[row]
    setp.ne.u32 %p4, %r1, 0;
    @%p4 bra DONE;

    ld.shared.f32 %f6, [sdata];

    // C[row] = sum
    cvt.u64.u32 %rd27, %r0;
    shl.b64 %rd28, %rd27, 2;
    add.u64 %rd29, %rd3, %rd28;
    st.global.f32 [%rd29], %f6;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("matvec_kernel")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        assert A.device.type == "cuda" and B.device.type == "cuda", "Inputs must be CUDA tensors"
        M = int(A.size(0))
        K = int(A.size(1))
        # Expect B shape (K, 1)
        assert B.numel() == K and B.size(0) == K, "B must be a vector of length K"
        C = torch.empty(M, 1, dtype=A.dtype, device=A.device)
        module = _get_ptx_module()
        module.launch(
            "matvec_kernel",
            grid=(M, 1, 1),
            block=(256, 1, 1),
            arguments=[A, B, C, i32(M), i32(K)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )
        return C

